def system(p):
    x, y, z, lam = p
    eq1 = y**3 + 3*z*x**2 - 2*lam*x
    eq2 = z**3 + 3*x*y**2 - 2*lam*y
    eq3 = x**3 + 3*y*z**2 - 2*lam*z
    eq4 = x**2 + y**2 + z**2 - 3
    return [eq1, eq2, eq3, eq4]

