import numpy as np
from scipy.optimize import fsolve

def system(p):
    x, y, z = p
    return [
        y**3 + 3*z*x**2 - 4*x,
        z**3 + 3*x*y**2 - 4*y,
        x**3 + 3*y*z**2 - 4*z
    ]

def find_solutions():
    solutions = []
    # We want to explore the space. Since x^2+y^2+z^2=3, 
    # x, y, z are in [-sqrt(3), sqrt(3)].
    # sqrt(3) is approx 1.732.

    # Sample a grid of points
    limit = 1.8
    grid_range = np.linspace(-limit, limit, 10)

    for x0 in grid_range:
        for y0 in grid_range:
            for z0 in grid_range:
                # Only start if it's somewhat near the sphere
                if abs(x0**2 + y0**2 + z0**2 - 3) < 1.0:
                    sol, info, ier, msg = fsolve(system, [x0, y0, z0], full_output=True)
                    if ier == 1:
                        x, y, z = sol
                        if abs(x**2 + y**2 + z**2 - 3) < 1e-6:
                            # Check for uniqueness
                            is_new = True
                            for s in solutions:
                                if np.allclose(s, sol, atol=1e-4):
                                    is_new = False
                                    break
                            if is_new:
                                solutions.append(sol)
    return solutions

sols = find_solutions()
print(f"Found {len(sols)} solutions:")
for s in sols:
    print(s)

import numpy as np
from scipy.optimize import minimize

def f(p):
    x, y, z = p
    return x*y**3 + y*z**3 + z*x**3

def constraint(p):
    x, y, z = p
    return x**2 + y**2 + z**2 - 3

def find_extrema():
    extrema = []
    # Sample a grid of phi and theta
    phi_vals = np.linspace(0, np.pi, 30)
    theta_vals = np.linspace(0, 2*np.pi, 60)

    for phi in phi_vals:
        for theta in theta_vals:
            x0 = np.sqrt(3) * np.sin(phi) * np.cos(theta)
            y0 = np.sqrt(3) * np.sin(phi) * np.sin(theta)
            z0 = np.sqrt(3) * np.cos(phi)

            # Maximize f
            res_max = minimize(lambda p: -f(p), [x0, y0, z0], constraints={'type': 'eq', 'fun': constraint})
            if res_max.success:
                val = -res_max.fun
                # Check if it's a maximum (we want f=3)
                if np.isclose(val, 3, atol=1e-4):
                    # Check for uniqueness
                    is_new = True
                    for ex in extrema:
                        if np.allclose(res_max.x, ex, atol=1e-4):
                            is_new = False
                            break
                    if is_new:
                        extrema.append(res_max.x)

            # Minimize f
            res_min = minimize(f, [x0, y0, z0], constraints={'type': 'eq', 'fun': constraint})
            if res_min.success:
                val = res_min.fun
                # Check if it's a minimum (we want f=3)
                if np.isclose(val, 3, atol=1e-4):
                    # Check for uniqueness
                    is_new = True
                    for ex in extrema:
                        if np.allclose(res_min.x, ex, atol=1e-4):
                            is_new = False
                            break
                    if is_new:
                        extrema.append(res_min.x)

    return extrema

extrema = find_extrema()
print(f"Total extrema found with f=3: {len(extrema)}")
for e in extrema:
    print(e)

import numpy as np
from scipy.optimize import fsolve

def system_l2(p):
    x, y, z = p
    return [y**3 + 3*z*x**2 - 4*x,
             z**3 + 3*x*y**2 - 4*y,
             x**3 + 3*y*z**2 - 4*z,
             x**2 + y**2 + z**2 - 3]

solutions = []
# Start from a larger grid
for i in np.linspace(-2, 2, 8):
    for j in np.linspace(-2, 2, 8):
        for k in np.linspace(-2, 2, 8):
            sol, info, ier, msg = fsolve(system_l2, [i, j, k], full_output=True)
            if ier == 1:
                # Verify
                if np.allclose(system_l2(sol), 0, atol=1e-6):
                    # Check if unique
                    new_sol = tuple(np.round(sol, 4))
                    if new_sol not in solutions:
                        solutions.append(new_sol)

print(f"Distinct solutions: {solutions}")

